#include <iostream>
#include <string>
#include <sstream>

std::string markdownToHtml(const std::string& markdown) {
    // Create a string stream to hold the markdown text
    std::stringstream markdownStream(markdown);

    // Create a string stream to hold the HTML text
    std::stringstream htmlStream;

    // Stream the markdown text to the HTML stream
    htmlStream << markdownStream;

    // Return the HTML text
    return htmlStream.str();
}

int main() {
    std::string markdown = "# Hello, World!\nThis is a test.";
    std::string html = markdownToHtml(markdown);
    std::cout << "Markdown: " << markdown << std::endl;
    std::cout << "HTML: " << html << std::endl;
    return 0;
}
```

